//! 🖼️ Fixed inline Canvas fragments preserve local paths, paint and full affine image placement without heap preparation.
use std::fmt::{self,Write};
use semio_framework_2d_engine::PathSegment;
use super::DrawingPaint;
pub const IMAGE_END:&str="\"}}";
pub struct CanvasFragment{bytes:[u8;4096],length:usize}
impl CanvasFragment{fn new()->Self{Self{bytes:[0;4096],length:0}}pub fn as_str(&self)->&str{std::str::from_utf8(&self.bytes[..self.length]).expect("inline Canvas formatting emits valid UTF-8")}}
impl Write for CanvasFragment{fn write_str(&mut self,text:&str)->fmt::Result{let end=self.length.checked_add(text.len()).ok_or(fmt::Error)?;if end>self.bytes.len(){return Err(fmt::Error);}self.bytes[self.length..end].copy_from_slice(text.as_bytes());self.length=end;Ok(())}}
fn matrix(out:&mut CanvasFragment,a:[f64;6])->Result<(),&'static str>{if a.iter().any(|v|!v.is_finite()){return Err("layout-drawing-canvas-nonfinite");}write!(out,"[{},{},{},{},{},{}]",a[0],a[1],a[2],a[3],a[4],a[5]).map_err(|_|"layout-drawing-canvas-fragment-limit")}
pub fn path_start(id:usize,affine:[f64;6])->Result<CanvasFragment,&'static str>{let mut out=CanvasFragment::new();write!(out,",{{\"id\":\"layout.drawing.path.{id}\",\"kind\":\"path\",\"transform\":").map_err(|_|"layout-drawing-canvas-fragment-limit")?;matrix(&mut out,affine)?;out.write_str(",\"segments\":[").map_err(|_|"layout-drawing-canvas-fragment-limit")?;Ok(out)}
pub fn segment(value:&PathSegment,comma:bool)->Result<CanvasFragment,&'static str>{let valid=match value{PathSegment::Move{to}|PathSegment::Line{to}=>to.iter().all(|v|v.is_finite()),PathSegment::Quad{ctrl,to}=>ctrl.iter().chain(to).all(|v|v.is_finite()),PathSegment::Cubic{ctrl1,ctrl2,to}=>ctrl1.iter().chain(ctrl2).chain(to).all(|v|v.is_finite()),PathSegment::Close=>true,_=>return Err("layout-drawing-canvas-unresolved-arc")};if !valid{return Err("layout-drawing-canvas-nonfinite");}let mut out=CanvasFragment::new();if comma{out.write_char(',').map_err(|_|"layout-drawing-canvas-fragment-limit")?;}match value{PathSegment::Move{to}=>write!(out,"{{\"kind\":\"move\",\"to\":[{},{}]}}",to[0],to[1]),PathSegment::Line{to}=>write!(out,"{{\"kind\":\"line\",\"to\":[{},{}]}}",to[0],to[1]),PathSegment::Quad{ctrl,to}=>write!(out,"{{\"kind\":\"quad\",\"ctrl\":[{},{}],\"to\":[{},{}]}}",ctrl[0],ctrl[1],to[0],to[1]),PathSegment::Cubic{ctrl1,ctrl2,to}=>write!(out,"{{\"kind\":\"cubic\",\"ctrl1\":[{},{}],\"ctrl2\":[{},{}],\"to\":[{},{}]}}",ctrl1[0],ctrl1[1],ctrl2[0],ctrl2[1],to[0],to[1]),PathSegment::Close=>out.write_str("{\"kind\":\"close\"}"),_=>return Err("layout-drawing-canvas-unresolved-arc")}.map_err(|_|"layout-drawing-canvas-fragment-limit")?;Ok(out)}
pub fn path_end(paint:DrawingPaint)->Result<CanvasFragment,&'static str>{if !paint.stroke_width.is_finite()||paint.stroke_width<0.0||paint.fill.iter().chain(paint.stroke.iter()).flatten().any(|v|!v.is_finite()){return Err("layout-drawing-canvas-invalid-paint");}let mut out=CanvasFragment::new();write!(out,"],\"fillRule\":\"{}\"",paint.fill_rule).map_err(|_|"layout-drawing-canvas-fragment-limit")?;if let Some(c)=paint.fill{write!(out,",\"fill\":{{\"color\":[{},{},{},{}]}}",c[0],c[1],c[2],c[3]).map_err(|_|"layout-drawing-canvas-fragment-limit")?;}if let Some(c)=paint.stroke.filter(|_|paint.stroke_width>0.0){write!(out,",\"stroke\":{{\"color\":[{},{},{},{}],\"width\":{},\"cap\":\"{}\",\"join\":\"{}\"}}",c[0],c[1],c[2],c[3],paint.stroke_width,paint.stroke_cap,paint.stroke_join).map_err(|_|"layout-drawing-canvas-fragment-limit")?;}out.write_char('}').map_err(|_|"layout-drawing-canvas-fragment-limit")?;Ok(out)}
pub fn image_start(id:usize,affine:[f64;6],rect:[f64;4])->Result<CanvasFragment,&'static str>{let[a,b,c,d,e,f]=affine;let[x,y,w,h]=rect;let mut out=CanvasFragment::new();write!(out,",{{\"id\":\"layout.drawing.image.{id}\",\"kind\":\"image\",\"transform\":").map_err(|_|"layout-drawing-canvas-fragment-limit")?;matrix(&mut out,[a*w,b*w,c*h,d*h,a*x+c*y+e,b*x+d*y+f])?;out.write_str(",\"image\":{\"width\":1,\"height\":1,\"src\":\"").map_err(|_|"layout-drawing-canvas-fragment-limit")?;Ok(out)}
